310→    private func detectAndUpdateLanguage(from text: String) {
311→        let recognizer = NLLanguageRecognizer()
312→        recognizer.processString(text)
313→
314→        // Get the dominant language
315→        if let dominantLanguage = recognizer.dominantLanguage {
316→            let languageCode = dominantLanguage.rawValue
317→
318→            if availableLocales.contains(languageCode) {
319→                lastSelectedLocale = languageCode
320→            } else {
321→                // Try to find a matching base language (e.g., "en" for "en-US")
322→                let baseLanguage = String(languageCode.prefix(2))
323→                if availableLocales.contains(baseLanguage) {
324→                    lastSelectedLocale = baseLanguage
325→                }
326→            }
327→        }
328→    }
