330→    private func fetchQuotedPostPreview() async {
331→        guard let quotedPostId else { return }
332→        isLoadingQuotedPost = true
333→        didFailToLoadQuotedPost = false
334→        defer { isLoadingQuotedPost = false }
335→
336→        do {
337→            let response = try await apolloClient.fetch(
338→                query: HackersPub.PostDetailQuery(id: quotedPostId, repliesAfter: nil),
339→                cachePolicy: .networkOnly
340→            )
341→            guard let quotedPost = response.data?.node?.asPost else {
342→                quotedPostPreview = nil
343→                didFailToLoadQuotedPost = true
344→                return
345→            }
346→            quotedPostPreview = quotedPost
347→        } catch {
348→            print("Error fetching quoted post preview: \(error)")
349→            quotedPostPreview = nil
350→            didFailToLoadQuotedPost = true
351→        }
352→    }
353→
354→    private func post() async {
355→        isPosting = true
356→        defer { isPosting = false }
357→
358→        do {
359→            let response = try await apolloClient.perform(
360→                mutation: HackersPub.CreateNoteMutation(
361→                    content: content,
362→                    language: lastSelectedLocale,
363→                    visibility: visibility,
364→                    replyTargetId: replyToPostId.map { .some($0) } ?? nil,
365→                    quotedPostId: quotedPostId.map { .some($0) } ?? nil
366→                )
367→            )
368→
369→            if let payload = response.data?.createNote.asCreateNotePayload {
370→                // Success - notify timelines to refresh and dismiss the view
371→                print("Posted note: \(payload.note.id)")
372→                NotificationCenter.default.post(name: Notification.Name("RefreshTimeline"), object: nil)
373→                dismiss()
374→            } else if let invalidInput = response.data?.createNote.asInvalidInputError {
375→                errorMessage = String(format: NSLocalizedString("compose.error.invalidInput", comment: "Invalid input error"), invalidInput.inputPath)
376→            } else if response.data?.createNote.asNotAuthenticatedError != nil {
377→                errorMessage = NSLocalizedString("compose.error.notAuthenticated", comment: "Not authenticated error")
378→            } else {
379→                errorMessage = NSLocalizedString("compose.error.failed", comment: "Failed to create post error")
380→            }
381→        } catch {
382→            print("Error creating note: \(error)")
383→            errorMessage = String(format: NSLocalizedString("compose.error.failedWithDetails", comment: "Failed to create post error with details"), error.localizedDescription)
384→        }
385→    }
386→}
