                            .verticalScroll(scrollState)
                    ) {
                        BasicTextField(
                            value = textFieldValue,
                            onValueChange = { newValue: TextFieldValue ->
                                textFieldValue = newValue
                                viewModel.updateContent(
                                    content = newValue.text,
