                                    .coerceIn(0, textFieldValue.text.length)
                                cursorRect = if (textFieldValue.text.isNotEmpty() || cursorPos == 0) {
                                    result.getCursorRect(cursorPos)
                                } else {
                                    Rect.Zero
                                }
