            if (uiState.isLoadingQuotedPost) {
                QuoteIndicator(isLoading = true)
                Spacer(modifier = Modifier.height(12.dp))
            } else if (uiState.quotedPost != null) {
                QuoteIndicator(isLoading = false, post = uiState.quotedPost)
                Spacer(modifier = Modifier.height(12.dp))
            }

