fragment ActorFields on Actor {
    id
    name
    handle
    avatarUrl
}

fragment MediaFields on PostMedium {
    url
    thumbnailUrl
    alt
    height
    width
}

fragment EngagementStatsFields on PostEngagementStats {
    replies
    reactions
    shares
    quotes
}

fragment PostFields on Post {
    __typename
    id
    name
    published
    summary
    content
    excerpt
    url
    iri
    viewerHasShared
    actor {
        ...ActorFields
    }
    media {
        ...MediaFields
    }
    engagementStats {
        ...EngagementStatsFields
    }
    mentions(first: 20) {
        edges {
            node {
                handle
            }
        }
    }
    quotedPost {
        ...SharedPostFields
    }
    reactionGroups {
        __typename
        ... on EmojiReactionGroup {
            emoji
            reactors {
                totalCount
                viewerHasReacted
            }
        }
        ... on CustomEmojiReactionGroup {
            customEmoji {
                id
                name
                imageUrl
            }
            reactors {
                totalCount
                viewerHasReacted
            }
        }
    }
}

fragment SharedPostFields on Post {
    __typename
    id
    name
    published
    summary
    content
    excerpt
    url
    iri
    viewerHasShared
    actor {
        ...ActorFields
    }
    media {
        ...MediaFields
    }
