                HorizontalDivider(thickness = 0.5.dp)
            }

            if (isLoadingMoreReplies) {
                item {
                    LoadingItem()
                }
            } else if (hasMoreReplies) {
                item {
                    TextButton(
                        onClick = onLoadMoreReplies,
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp)
                    ) {
                        Text(stringResource(R.string.load_more))
                    }
                }
            }
        }
    }
}

