                val replies = node.replies.edges.mapNotNull { edge ->
                    edge.node.postFields.toPost(edge.node.sharedPost?.sharedPostFields?.toPost())
                }

                Result.success(
                    PostDetailResult(
                        post = post,
                        reactionGroups = reactionGroups,
                        replies = replies,
                        hasMoreReplies = node.replies.pageInfo.hasNextPage,
